import { test } from "node:test";
import assert from "node:assert/strict";
import { HealApi, VERSION } from "../src/api.js";
import { ATTEMPT, server, reply, waitFor } from "./helpers.js";
import type { Capture, Fetch } from "../src/types.js";
const capture: Capture = {
  traceId: "test",
  request: {
    method: "POST",
    url: "https://example.com",
    headers: {},
    body: {},
  },
  response: { statusCode: 400, body: "bad", truncated: false },
  responseTimeMs: 1,
};

test("heal calls have a wall-clock deadline", async (t) => {
  const service = await server(() => {});
  t.after(service.close);
  const api = new HealApi(fetch, "key", service.url + "/", 30);
  const started = performance.now();
  assert.equal(await api.heal(capture, new AbortController().signal), null);
  assert.ok(performance.now() - started < 1000);
});

test("rejects oversized heal responses", async (t) => {
  const service = await server((_req, res) =>
    reply(res, 200, { status: "patched", extra: "x".repeat(1_100_000) })
  );
  t.after(service.close);
  const api = new HealApi(fetch, "key", service.url + "/");
  assert.equal(await api.heal(capture, new AbortController().signal), null);
});

test("outcome failures emit warnings", async (t) => {
  const warnings: string[] = [];
  t.mock.method(process, "emitWarning", (message: string) => {
    warnings.push(message);
  });
  const service = await server((_req, res) => reply(res, 400, {}));
  t.after(service.close);
  const api = new HealApi(fetch, "key", service.url + "/");
  api.report(ATTEMPT, { response: { statusCode: 200 } });
  await waitFor(() => warnings.length === 1);
  assert.equal(warnings.length, 1);
});

test("outcome concurrency is bounded", async (t) => {
  let dropped = 0;
  t.mock.method(process, "emitWarning", (message: string) => {
    if (message.includes("capacity")) dropped++;
  });
  const service = await server(() => {});
  t.after(service.close);
  const api = new HealApi(fetch, "key", service.url + "/", 1000, 100);
  for (let i = 0; i < 70; i++)
    api.report(ATTEMPT, { response: { statusCode: 200 } });
  assert.equal(dropped, 6);
  assert.ok(api.pending.size <= 64);
  await waitFor(() => api.pending.size === 0, 5000);
});

// The app derives a request's `sdk`/`sdk_version` from this header and nothing else,
// falling back to the captured exchange's own User-Agent — which never matches — so a
// dropped header costs attribution silently rather than failing a call.
test("heal requests identify the SDK by User-Agent", async (t) => {
  let userAgent: string | undefined;
  const service = await server((req, res) => {
    userAgent = req.headers["user-agent"];
    reply(res, 200, { status: "unverified", healAttemptId: ATTEMPT });
  });
  t.after(service.close);
  const api = new HealApi(fetch, "key", service.url + "/");
  await api.heal(capture, new AbortController().signal);
  assert.equal(userAgent, `mnfst-node/${VERSION}`);
});

test("outcome reports identify the SDK by User-Agent", async (t) => {
  let userAgent: string | undefined;
  const service = await server((req, res) => {
    userAgent = req.headers["user-agent"];
    reply(res, 200, { status: "recorded" });
  });
  t.after(service.close);
  const api = new HealApi(fetch, "key", service.url + "/");
  api.report(ATTEMPT, { response: { statusCode: 200 } });
  await waitFor(() => api.pending.size === 0);
  assert.equal(userAgent, `mnfst-node/${VERSION}`);
});

test("hello announces the install without blocking or throwing", async () => {
  const calls: { url: string; init: RequestInit }[] = [];
  const api = new HealApi(
    (async (url: URL | RequestInfo, init?: RequestInit) => {
      calls.push({ url: String(url), init: init ?? {} });
      return new Response('{"status":"ok"}', { status: 200 });
    }) as unknown as Fetch,
    "k",
    "https://api.example.test/"
  );

  // Returns synchronously: a handshake must never delay startup.
  assert.equal(api.hello("node-22.0.0"), undefined);
  await new Promise((r) => setImmediate(r));

  assert.equal(calls.length, 1);
  const call = calls[0];
  assert.ok(call);
  assert.equal(call.url, "https://api.example.test/v1/hello");
  assert.equal(call.init.method, "POST");
  // Carries the runtime and nothing else — identity rides in the user-agent.
  assert.deepEqual(JSON.parse(String(call.init.body)), {
    runtime: "node-22.0.0",
  });
  const headers = call.init.headers as Record<string, string>;
  assert.match(String(headers["user-agent"]), /^mnfst-node\//);
});

test("a failing hello is swallowed", async () => {
  const api = new HealApi(
    (async () => {
      throw new Error("network down");
    }) as unknown as Fetch,
    "k",
    "https://api.example.test/"
  );
  // An app that cannot reach Manifest must still boot cleanly.
  assert.equal(api.hello("node-22.0.0"), undefined);
  await new Promise((r) => setImmediate(r));
});

test("sendRequests throws only when a retry could help", async (t) => {
  let status = 202;
  let body: unknown = { accepted: 1 };
  const service = await server((_req, res) => reply(res, status, body));
  t.after(service.close);
  const api = new HealApi(fetch, "key", service.url + "/");
  const call = { traceId: "t", method: "GET", url: "https://a.com/x", statusCode: 200,
    responseTimeMs: 1, occurredAt: new Date(0).toISOString() };
  for (status of [202, 400, 401, 404]) await api.sendRequests([call]);
  for (status of [429, 500, 503]) await assert.rejects(api.sendRequests([call]));
  status = 403; body = { error: "project_disabled" };
  await api.sendRequests([call]);
  assert.equal(api.enabled(), false);
});

import { test } from 'node:test';
import assert from 'node:assert/strict';
import { fetch as undiciFetch, request as undiciRequest } from 'undici';
import { installUndici } from '../src/undici.js';
import { rig } from './helpers.js';

// Libraries such as @vercel/blob import fetch from the undici package, which
// never goes through globalThis.fetch or node:http.
test('a call through the undici package is tracked', async t => {
  const r = await rig(); t.after(r.close); t.after(installUndici(r.runtime));
  const response = await undiciFetch(r.provider.url + '/ok?token=secret', { method: 'POST', body: '{"limit":50}' });
  assert.deepEqual(await response.json(), { received: { limit: 50 } });
  await r.runtime.tracker.flush();
  assert.deepEqual(r.tracked.map(c => [c.method, c.url, c.statusCode]), [['POST', r.provider.url + '/ok', 200]]);
});

test('undici request() calls are tracked too', async t => {
  const r = await rig(); t.after(r.close); t.after(installUndici(r.runtime));
  const { statusCode, body } = await undiciRequest(r.provider.url + '/ok', { method: 'POST', body: '{}' });
  await body.text();
  await r.runtime.tracker.flush();
  assert.deepEqual(r.tracked.map(c => [c.url, c.statusCode]), [[r.provider.url + '/ok', statusCode]]);
});

test('a fetch captured before install is tracked through the built-in undici', async t => {
  const r = await rig(); t.after(r.close); t.after(installUndici(r.runtime));
  const captured = globalThis.fetch; // Node's own fetch, never wrapped by the runtime here
  await (await captured(r.provider.url + '/ok', { method: 'POST', body: '{}' })).text();
  await r.runtime.tracker.flush();
  assert.deepEqual(r.tracked.map(c => c.url), [r.provider.url + '/ok']);
});

test('a call through the runtime fetch is tracked once, not also by undici', async t => {
  const r = await rig(); t.after(r.close); t.after(installUndici(r.runtime));
  await (await r.runtime.fetch(r.provider.url + '/ok', { method: 'POST', body: '{}' })).text();
  await r.runtime.tracker.flush();
  assert.equal(r.tracked.length, 1);
});

test('a healed call is neither tracked by undici nor its retry', async t => {
  const r = await rig(); t.after(r.close); t.after(installUndici(r.runtime));
  const response = await r.runtime.fetch(r.provider.url + '/repair', { method: 'POST', body: '{"limit":500}' });
  assert.equal(response.status, 200);
  await r.runtime.tracker.flush();
  assert.equal(r.captures.length, 1);
  assert.deepEqual(r.tracked, []);
});

// A regression loops forever (each batch tracked, sent, tracked again), so fail fast.
test("Manifest's own calls are never tracked", { timeout: 5000 }, async t => {
  const r = await rig(); t.after(r.close); t.after(installUndici(r.runtime));
  await (await undiciFetch(r.provider.url + '/ok', { method: 'POST', body: '{}' })).text();
  await r.runtime.tracker.flush(); // this send goes through the built-in undici
  r.runtime.api.hello('node-test');
  await new Promise(resolve => setTimeout(resolve, 100));
  await r.runtime.tracker.flush();
  assert.deepEqual(r.tracked.map(c => c.url), [r.provider.url + '/ok']);
});

test('uninstalling stops tracking', async t => {
  const r = await rig(); t.after(r.close);
  installUndici(r.runtime)();
  await (await undiciFetch(r.provider.url + '/ok', { method: 'POST', body: '{}' })).text();
  await r.runtime.tracker.flush();
  assert.deepEqual(r.tracked, []);
});

test('the allowlist and denylist apply to undici calls too', async t => {
  const r = await rig({ filter: { allow: null, deny: [{ host: '127.0.0.1', path: '/denied' }] } });
  t.after(r.close); t.after(installUndici(r.runtime));
  for (const path of ['/denied', '/ok']) await (await undiciFetch(r.provider.url + path, { method: 'POST', body: '{}' })).text();
  await r.runtime.tracker.flush();
  assert.deepEqual(r.tracked.map(c => new URL(c.url).pathname), ['/ok']);
});

