import { captureResponse } from "./capture.js";
import { boundedJson, isObject } from "./wire.js";
import { keepAlive } from "./serverless.js";
import type { Capture, Fetch, HealResult, Outcome, TrackedCall } from "./types.js";
export const VERSION = "7.4.0";
const MAX_HEALS_IN_FLIGHT = 8;
export const warn = (message: string) =>
  process.emitWarning(message, { code: "MNFST" });
export class HealApi {
  private disabledUntil = 0;
  private inFlight = 0;
  /** @internal In-flight outcome reports; exposed so tests can await delivery. */
  readonly pending = new Set<Promise<void>>();
  constructor(
    private rawFetch: Fetch,
    private key: string,
    private url: string,
    private timeoutMs = 60_000,
    private reportTimeoutMs = 5000
  ) {}
  enabled() {
    return performance.now() >= this.disabledUntil;
  }
  /**
   * Whether a heal call would be sent right now: the project is not disabled
   * and a heal slot is free. A healable failure that cannot be sent is tracked
   * instead, so it is never lost from both ledgers.
   */
  canHeal() {
    return this.enabled() && this.inFlight < MAX_HEALS_IN_FLIGHT;
  }
  private headers() {
    return {
      authorization: `Bearer ${this.key}`,
      "content-type": "application/json",
      "user-agent": `mnfst-node/${VERSION}`,
    };
  }
  async heal(
    capture: Capture,
    signal: AbortSignal
  ): Promise<HealResult | null> {
    if (!this.canHeal()) return null;
    this.inFlight++;
    const controller = new AbortController();
    const timer = setTimeout(() => controller.abort(), this.timeoutMs);
    try {
      const response = await this.rawFetch(new URL("v1/heal", this.url), {
        method: "POST",
        headers: this.headers(),
        body: JSON.stringify(capture),
        signal: AbortSignal.any([signal, controller.signal]),
        redirect: "error",
      });
      if (response.status !== 200 && response.status !== 403) {
        void response.body?.cancel().catch(() => {});
        return null;
      }
      const captured = await captureResponse(
        response,
        1_048_576,
        this.timeoutMs
      );
      void captured.response.body?.cancel().catch(() => {});
      if (
        !captured.complete ||
        !isObject(captured.body) ||
        !boundedJson(captured.body)
      )
        return null;
      if (
        response.status === 403 &&
        captured.body.error === "project_disabled"
      ) {
        this.disabledUntil = performance.now() + 300_000;
      }
      if (response.status !== 200 || typeof captured.body.status !== "string")
        return null;
      return {
        status: captured.body.status,
        ...(typeof captured.body.healAttemptId === "string"
          ? { healAttemptId: captured.body.healAttemptId }
          : {}),
        ...(Array.isArray(captured.body.operations)
          ? { operations: captured.body.operations }
          : {}),
        ...(isObject(captured.body.healedRequest)
          ? { healedRequest: captured.body.healedRequest }
          : {}),
      };
    } catch {
      return null;
    } finally {
      clearTimeout(timer);
      this.inFlight--;
    }
  }
  /**
   * Announce this install: "I am installed."
   *
   * Without it, a broken install and a healthy app look identical from the
   * dashboard — both are silence. Four causes hide behind that silence (key
   * unset, key invalid, app not restarted, SDK never loaded), and an app with
   * no failing calls produces exactly the same nothing.
   *
   * Deliberately fire-and-forget and deliberately quiet. It carries no
   * application data: the name and version ride in the user-agent this class
   * already sends, so the body is the runtime and nothing else. A failure is
   * not warned about — the dashboard showing "not connected" IS the signal,
   * and an app that cannot reach Manifest must not print on every boot.
   *
   * Uses `rawFetch`, so the handshake cannot be intercepted by our own patch.
   */
  hello(runtime: string): void {
    const controller = new AbortController();
    const timer = setTimeout(() => controller.abort(), this.reportTimeoutMs);
    void this.rawFetch(new URL("v1/hello", this.url), {
      method: "POST",
      headers: this.headers(),
      body: JSON.stringify({ runtime }),
      signal: controller.signal,
      redirect: "error",
    })
      .then((response) => {
        void response.body?.cancel().catch(() => {});
      })
      .catch(() => {})
      .finally(() => clearTimeout(timer));
  }

  /**
   * Ship one batch of tracked calls to `POST /v1/requests`. Throws only when a
   * retry could help (network error, timeout, 429, 5xx), so the buffer retries
   * once; any other answer, including 404 from a backend that predates the
   * route, drops the batch quietly. Uses `rawFetch`, so the send is never
   * tracked or healed by our own patch.
   */
  async sendRequests(calls: TrackedCall[], signal?: AbortSignal): Promise<void> {
    if (!this.enabled() || calls.length === 0) return;
    const controller = new AbortController();
    const timer = setTimeout(() => controller.abort(), this.reportTimeoutMs);
    try {
      const response = await this.rawFetch(new URL("v1/requests", this.url), {
        method: "POST",
        headers: this.headers(),
        body: JSON.stringify({ requests: calls }),
        signal: signal ? AbortSignal.any([signal, controller.signal]) : controller.signal,
        redirect: "error",
      });
      if (response.status === 403) {
        const body = await response.json().catch(() => null);
        if (isObject(body) && body.error === "project_disabled") {
          this.disabledUntil = performance.now() + 300_000;
        }
        return;
      }
      void response.body?.cancel().catch(() => {});
      if (response.status === 429 || response.status >= 500) {
        throw new Error(`tracked calls refused (${response.status})`);
      }
    } finally {
      clearTimeout(timer);
    }
  }

  report(id: string | undefined, outcome: Outcome): void {
    if (!id) return;
    if (this.pending.size >= 64) {
      warn("Outcome report capacity reached; report dropped");
      return;
    }
    const promise = this.send(id, outcome);
    this.pending.add(promise);
    void promise.then(() => this.pending.delete(promise));
    // A serverless function freezes once it responds; let the platform wait.
    keepAlive(promise);
  }
  private async send(id: string, outcome: Outcome): Promise<void> {
    const controller = new AbortController();
    const timer = setTimeout(() => controller.abort(), this.reportTimeoutMs);
    try {
      const response = await this.rawFetch(
        new URL(`v1/heal-attempts/${encodeURIComponent(id)}`, this.url),
        {
          method: "PATCH",
          headers: this.headers(),
          body: JSON.stringify(outcome),
          signal: controller.signal,
          redirect: "error",
        }
      );
      void response.body?.cancel().catch(() => {});
      if (!response.ok)
        warn("Outcome report rejected; attempt remains unconfirmed");
    } catch {
      warn("Outcome report failed; attempt remains unconfirmed");
    } finally {
      clearTimeout(timer);
    }
  }
}

import { AsyncLocalStorage } from 'node:async_hooks';
import { subscribe, unsubscribe } from 'node:diagnostics_channel';
import type { Runtime } from './runtime.js';

/**
 * Calls made through the undici package directly (`@vercel/blob`, and any
 * client that imports undici's fetch or request) never pass through
 * `globalThis.fetch` or `node:http`, so neither patch sees them. Node's own
 * fetch and the undici package both publish every request on the same
 * diagnostics channels, so watching those covers them all, and a fetch
 * captured before `manifest()` ran as well.
 *
 * Observation only: a channel sees a response and cannot replace it, so these
 * calls are tracked, never healed.
 */

// Set while the runtime's own fetch is at work, so a call it already handles
// (and its retry) is not counted a second time by the channels below.
const handling = new AsyncLocalStorage<true>();

export const handled = <T>(work: () => T): T => handling.run(true, work);
/** Whether the current call is the SDK's own work, or a call the runtime already handles. */
export const isHandled = (): boolean => handling.getStore() === true;

interface UndiciRequest { method?: string; origin?: unknown; path?: string }
interface Started { startedAt: number; started: number }

export function installUndici(runtime: Runtime): () => void {
  const manifestOrigin = new URL(runtime.options.url).origin;
  const inFlight = new WeakMap<object, Started>();
  const onCreate = (message: unknown) => {
    const { request } = message as { request: UndiciRequest };
    // Manifest's own sends go out through Node's fetch too; tracking them
    // would make every batch of tracked calls produce another.
    if (handling.getStore() || String(request.origin) === manifestOrigin) return;
    inFlight.set(request, { startedAt: Date.now(), started: performance.now() });
  };
  const onHeaders = (message: unknown) => {
    const { request, response } = message as { request: UndiciRequest; response: { statusCode: number } };
    const started = inFlight.get(request);
    if (!started) return;
    inFlight.delete(request);
    let url: string;
    try { url = new URL(request.path ?? '/', String(request.origin)).href; } catch { return; }
    // The allowlist and denylist apply here as everywhere: an excluded call is never tracked.
    if (runtime.excluded(url)) return;
    runtime.track(request.method ?? 'GET', () => url, response.statusCode, started.startedAt,
      performance.now() - started.started);
  };
  subscribe('undici:request:create', onCreate);
  subscribe('undici:request:headers', onHeaders);
  return () => {
    unsubscribe('undici:request:create', onCreate);
    unsubscribe('undici:request:headers', onHeaders);
  };
}

import { test } from 'node:test';
import assert from 'node:assert/strict';
import dns from 'node:dns';
import http from 'node:http';
import { installHttp } from '../src/http.js';
import { rig } from './helpers.js';

function call(url: string, options: http.RequestOptions, body?: string) {
  return new Promise<{ status: number | undefined; body: string }>((resolve, reject) => {
    const request = http.request(url, options, response => {
      const chunks: Buffer[] = [];
      response.on('data', chunk => chunks.push(Buffer.from(chunk)));
      response.on('end', () => resolve({ status: response.statusCode, body: Buffer.concat(chunks).toString() }));
      response.on('error', reject);
    });
    request.on('error', reject);
    request.end(body);
  });
}

// One install for the whole file: each installHttp wraps the previous one.
test('node:http heals only a call a fetch replay reaches the same way', async t => {
  const r = await rig();
  t.after(r.close);
  installHttp(r.runtime);
  const body = JSON.stringify({ limit: 500 });

  await t.test('a plain request is healed', async () => {
    assert.equal((await call(r.provider.url + '/repair', { method: 'POST' }, body)).status, 200);
    assert.equal(r.captures.length, 1);
  });

  await t.test('a Host header naming another server is never replayed there', async () => {
    const result = await call(r.provider.url + '/repair', { method: 'POST', headers: { host: 'elsewhere.test' } }, body);
    assert.equal(result.status, 400);
    assert.equal(r.captures.length, 1);
    assert.equal(r.requests.at(-1)!.headers.host, 'elsewhere.test');
  });

  await t.test('a custom agent or connection option is not replayed through fetch', async () => {
    const agent = new (class ProxyAgent extends http.Agent {
      connect() { return undefined; }
    })();
    assert.equal((await call(r.provider.url + '/repair', { method: 'POST', agent }, body)).status, 400);
    const lookup = ((host, options, callback) => dns.lookup(host, options, callback)) as http.RequestOptions['lookup'];
    assert.equal((await call(r.provider.url + '/repair', { method: 'POST', lookup }, body)).status, 400);
    const tls = new http.Agent({ keepAlive: true, rejectUnauthorized: false } as http.AgentOptions);
    assert.equal((await call(r.provider.url + '/repair', { method: 'POST', agent: tls }, body)).status, 400);
    assert.equal(r.captures.length, 1);
    // A standard keep-alive agent carries nothing a replay would lose.
    const keepAlive = new http.Agent({ keepAlive: true });
    assert.equal((await call(r.provider.url + '/repair', { method: 'POST', agent: keepAlive }, body)).status, 200);
    assert.equal(r.captures.length, 2);
    // A keep-alive subclass (agentkeepalive, under the OpenAI and Anthropic SDKs) is healed too.
    const subclass = new (class KeepAliveAgent extends http.Agent {})({ keepAlive: true });
    assert.equal((await call(r.provider.url + '/repair', { method: 'POST', agent: subclass }, body)).status, 200);
    assert.equal(r.captures.length, 3);
    keepAlive.destroy(); tls.destroy(); agent.destroy(); subclass.destroy();
  });

  await t.test('a method fetch refuses gets the original response, not an error', async () => {
    const result = await call(r.provider.url + '/same', { method: 'TRACE' });
    assert.equal(result.status, 400);
