export const error = { error: { message: 'range of limit should be [1, 100]', param: 'limit', code: 'invalid_value', type: 'validation_error' } };
export async function jsonBody(request: IncomingMessage) {
  const chunks = [];
  for await (const chunk of request) chunks.push(Buffer.from(chunk));
  const text = Buffer.concat(chunks).toString();
  if (request.headers['content-type']?.split(';', 1)[0]?.trim().toLowerCase() === 'application/x-www-form-urlencoded') {
    return Object.fromEntries(new URLSearchParams(text));
  }
  return JSON.parse(text || 'null');
}
export function reply(response: ServerResponse, status: number, body: unknown) {
  response.writeHead(status, { 'content-type': 'application/json' }); response.end(JSON.stringify(body));
}
export async function server(handler: (req: IncomingMessage, res: ServerResponse) => void | Promise<void>) {
  const instance = createServer((req, res) => { Promise.resolve(handler(req, res)).catch(() => { if (!res.headersSent) reply(res, 500, { error: 'fixture error' }); else res.destroy(); }); });
  instance.listen(0, '127.0.0.1'); await once(instance, 'listening');
  const address = instance.address();
  if (!address || typeof address === 'string') throw new Error('no address');
  return { url: `http://127.0.0.1:${address.port}`, close: async () => {
    const done = new Promise<void>((resolve, reject) => instance.close(error => error ? reject(error) : resolve()));
    instance.closeAllConnections(); await done;
  } };
}
export async function waitFor(predicate: () => boolean, timeoutMs = 3000): Promise<void> {
  const deadline = performance.now() + timeoutMs;
  while (performance.now() < deadline) {
    if (predicate()) return;
    await new Promise(resolve => setTimeout(resolve, 5));
  }
  throw new Error('waitFor timed out');
}
export async function rig(options: Partial<ResolvedOptions> = {}) {
  const captures: Capture[] = []; const outcomes: Outcome[] = []; const tracked: TrackedCall[] = [];
  const requests: { path: string; body: any; headers: IncomingMessage['headers'] }[] = [];
  const config: { result: HealResult; disabled: boolean; reportStatus: number; requestsStatus: number;
    requestsDelayMs: number; reportDelayMs: number; finish?: () => void } = {
    result: { status: 'unverified', healAttemptId: ATTEMPT, healedRequest: { body: { limit: 100 } } }, disabled: false, reportStatus: 200,
    requestsStatus: 202, requestsDelayMs: 0, reportDelayMs: 0,
  };
  const api = await server(async (req, res) => {
    const body = await jsonBody(req);
    if (req.url === '/v1/requests') {
      if (config.requestsDelayMs) await new Promise(resolve => setTimeout(resolve, config.requestsDelayMs));
      if (config.requestsStatus === 202) tracked.push(...body.requests);
      reply(res, config.requestsStatus, { accepted: body.requests.length }); return;
    }
    if (req.url === '/v1/heal') {
      captures.push(body); reply(res, config.disabled ? 403 : 200, config.disabled ? { error: 'project_disabled' } : config.result);
    } else if (req.url === `/v1/heal-attempts/${ATTEMPT}`) {
      const keys = Object.keys(body);
      const valid = keys.length === 1 && (keys[0] === 'response' ? body.response.statusCode >= 200 && body.response.statusCode <= 599 :
        keys[0] === 'failure' && ['transport_error', 'not_attempted'].includes(body.failure.kind));
      if (!valid) { reply(res, 400, { error: 'contract mismatch' }); return; }
      if (config.reportDelayMs) await new Promise(resolve => setTimeout(resolve, config.reportDelayMs));
      outcomes.push(body); reply(res, config.reportStatus, { status: 'recorded' });
    } else reply(res, 404, {});
  });
  const provider = await server(async (req, res) => {
    const body = await jsonBody(req); const path = req.url!;
    requests.push({ path, body, headers: req.headers });
    if (path.startsWith('/gzip')) {
      const status = body?.limit > 100 ? 400 : 200;
      const payload = status === 400 ? error : { received: body };
      res.writeHead(status, { 'content-type': 'application/json', 'content-encoding': 'gzip' });
      res.end(gzipSync(JSON.stringify(payload))); return;
    }
    if (body?.limit > 100 || path.startsWith('/same')) { reply(res, 400, error); return; }
    if (path.startsWith('/transport')) { res.destroy(); return; }
    if (path.startsWith('/stream')) {
      res.writeHead(200, { 'content-type': 'text/plain' }); res.write('first');
      config.finish = () => res.end('last'); return;
    }
    reply(res, 200, { received: body });
  });
  const runtime = new Runtime({ key: 'project-key', url: api.url + '/', ...options }, fetch);
  return { api, provider, runtime, config, captures, outcomes, requests, tracked,
    close: async () => { await waitFor(() => runtime.api.pending.size === 0); await Promise.all([api.close(), provider.close()]); } };
}

import { test } from 'node:test';
import assert from 'node:assert/strict';
import { spawn } from 'node:child_process';
import { once } from 'node:events';
import { fileURLToPath } from 'node:url';
import { rig } from './helpers.js';

const script = fileURLToPath(new URL('./fixtures/exit-flush.ts', import.meta.url));

async function runScript(env: Record<string, string>): Promise<{ code: number; ms: number }> {
  const started = performance.now();
  const child = spawn(process.execPath, ['--import', 'tsx', script], { env: { ...process.env, ...env }, stdio: 'ignore' });
  const [code] = await once(child, 'exit');
  return { code: code as number, ms: performance.now() - started };
}

test('a script that ends sends its tracked calls on the way out, never its own sends', async t => {
  const r = await rig(); t.after(r.close);
  const { code } = await runScript({ MANIFEST_URL: r.api.url, PROVIDER_URL: r.provider.url, WAIT_MS: '5500' });
  assert.equal(code, 0);
  // Two calls: one sent by the interval, one at exit. A tracked send would be a third.
  assert.deepEqual(r.tracked.map(c => c.url), [r.provider.url + '/ok', r.provider.url + '/ok']);
});

test('a script never hangs on its way out when Manifest does not answer', async t => {
  const r = await rig(); t.after(r.close);
  r.config.requestsDelayMs = 60_000;
  const { code, ms } = await runScript({ MANIFEST_URL: r.api.url, PROVIDER_URL: r.provider.url });
  assert.equal(code, 0);
  assert.ok(ms < 6000, `exit took ${ms.toFixed(0)} ms`);
});

import { test } from 'node:test';
import assert from 'node:assert/strict';
import { randomUUID } from 'node:crypto';
import { manifest } from '../src/index.js';
import { server, jsonBody, reply, error, waitFor } from './helpers.js';

test('real app: successful repair, failed retry and transport error evidence', { skip: !process.env.MNFST_TEST_APP_URL }, async t => {
  const base = process.env.MNFST_TEST_APP_URL!;
  const original = fetch;
  const signup = await original(base + '/api/auth/sign-up/email', { method: 'POST', headers: { 'content-type': 'application/json', origin: base }, body: JSON.stringify({ name: 'Node SDK test', email: `node-${randomUUID()}@example.test`, password: 'LocalNodeConformance-2026!' }) });
  assert.equal(signup.status, 200);
  const cookie = signup.headers.getSetCookie().map(value => value.split(';')[0]).join('; ');
  const customer = async (path: string, body: unknown) => {
    const response = await original(base + path, { method: 'POST', headers: { origin: base, cookie, 'content-type': 'application/json' }, body: JSON.stringify(body) });
    assert.equal(response.status, 201); return response.json();
  };
  const project = await customer('/api/customer/projects', { name: 'Node SDK conformance' });
  const key = await customer(`/api/customer/projects/${project.id}/keys`, {});
  const outcomes: { code: number; body: any }[] = [];
  globalThis.fetch = async (input, init) => {
    const response = await original(input, init);
    const url = input instanceof Request ? input.url : String(input);
    if (url.includes('/v1/heal-attempts/')) outcomes.push({ code: response.status, body: await response.clone().json() });
    return response;
  };
  t.after(() => { globalThis.fetch = original; });
  const provider = await server(async (req, res) => {
    const body = await jsonBody(req);
    if (body.limit > 100 || req.url!.endsWith('/same')) reply(res, 400, error);
    else if (req.url!.endsWith('/transport')) res.destroy();
    else reply(res, 200, body);
  });
  t.after(provider.close);
  manifest({ key: key.key, url: base });
  const prefix = provider.url + '/node' + randomUUID().replaceAll('-', '');
  const repaired = await fetch(prefix + '/success', { method: 'POST', body: '{"limit":500}' });
  assert.equal(repaired.status, 200); assert.deepEqual(await repaired.json(), { limit: 100 });
  for (const path of ['/same', '/transport']) {
    const response = await fetch(prefix + path, { method: 'POST', body: '{"limit":500}' });
    assert.equal(response.status, 400); await response.body?.cancel();
  }
  await waitFor(() => outcomes.length === 3, 10_000);
  assert.equal(outcomes.length, 3); assert.ok(outcomes.every(item => item.code === 200));
  assert.deepEqual(outcomes.map(item => item.body.status).sort(), ['failed', 'inconclusive', 'succeeded']);
});

import { test } from 'node:test';
import assert from 'node:assert/strict';
import http from 'node:http';
import { installHttp } from '../src/http.js';
import { rig, waitFor } from './helpers.js';

const denied = { allow: null, deny: [{ host: '127.0.0.1', path: '/repair' }] };

test('fetch: a denied route is neither healed nor tracked, and its response is untouched', async t => {
  const r = await rig({ filter: denied });
  t.after(r.close);
  const failed = await r.runtime.fetch(r.provider.url + '/repair', { method: 'POST', body: JSON.stringify({ limit: 500 }) });
  const ok = await r.runtime.fetch(r.provider.url + '/ok');
  await r.runtime.tracker.flush(1000);
  assert.equal(failed.status, 400);
  assert.equal((await failed.json()).error.code, 'invalid_value');
  assert.equal(ok.status, 200);
  assert.equal(r.captures.length, 0);
  // The route is denied, not the host: the other call on it is tracked as usual.
  assert.deepEqual(r.tracked.map(c => new URL(c.url).pathname), ['/ok']);
  assert.equal(r.requests.length, 2);
});

test('node:http: a host off the allowlist is neither healed nor tracked', async t => {
  const r = await rig({ filter: { allow: [{ host: 'example.com', path: null }], deny: [] } });
  t.after(r.close);
  installHttp(r.runtime);
  const status = await new Promise<number | undefined>((resolve, reject) => {
    const request = http.request(r.provider.url + '/repair', { method: 'POST' }, response => {
      response.resume(); response.on('end', () => resolve(response.statusCode)); response.on('error', reject);
    });
    request.on('error', reject);
    request.end(JSON.stringify({ limit: 500 }));
  });
  await r.runtime.tracker.flush(1000);
  assert.equal(status, 400);
  assert.equal(r.captures.length, 0);
  assert.equal(r.tracked.length, 0);
});

test('a patch never sends the retry to a denied route', async t => {
  const r = await rig({ filter: { allow: null, deny: [{ host: '127.0.0.1', path: '/private' }] } });
  t.after(r.close);
  r.config.result = { status: 'unverified', healAttemptId: '33333333-3333-4333-8333-333333333333',
    healedRequest: { url: r.provider.url + '/private', body: { limit: 100 } } };
  const response = await r.runtime.fetch(r.provider.url + '/repair', { method: 'POST', body: JSON.stringify({ limit: 500 }) });
  assert.equal(response.status, 400);
  assert.equal(r.captures.length, 1);
  assert.deepEqual(r.requests.map(request => request.path), ['/repair']);
  await waitFor(() => r.outcomes.length === 1);
  assert.deepEqual(r.outcomes[0], { failure: { kind: 'not_attempted', message: 'replay_not_attempted' } });
});
